import subprocess, time, signal, os

def run(args, env=None, duration=1.0):
    e = dict(os.environ)
    if env: e.update(env)
    p = subprocess.Popen(["./executable"]+args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=e)
    time.sleep(duration)
    alive = p.poll() is None
    print(f"alive? {alive} poll={p.poll()}")
    if alive:
        p.send_signal(signal.SIGINT)
        try:
            out, err = p.communicate(timeout=3)
        except subprocess.TimeoutExpired:
            p.kill()
            out, err = p.communicate()
        print(f"EXIT={p.returncode} OUT={repr(out[:1000])} ERR={repr(err[:2000])}")
    else:
        out, err = p.communicate()
        print(f"EXIT={p.returncode} OUT={repr(out[:1000])} ERR={repr(err[:2000])}")
    print("---")

for i in range(3):
    print(f"TRY {i} CASE1")
    run(["-b", "-n", "0.5", "echo", "hi"], env={'HWATCH': '-s "sh -c"'}, duration=1.0)
for i in range(2):
    print(f"TRY {i} CASE2")
    run(["-b", "-n", "0.5", "-s", '"unclosed', "echo", "hi"], duration=1.0)
PY"}

