fn valid_key(key: &str) -> bool {
    if key.is_empty() {
        return false;
    }
    // single char always valid? (any single char)
    if key.chars().count() == 1 {
        return true;
    }
    // check special list (case-insensitive)
    let lower = key.to_lowercase();
    let specials = ["up","down","left","right","home","end","pageup","pagedown","insert","delete","backtab","tab","enter","esc","space","backspace","del","ins","f1","f2","f3","f4","f5","f6","f7","f8","f9","f10","f11","f12"];
    if specials.contains(&lower.as_str()) {
        return true;
    }
    // modifier-key: split by '-'
    if key.contains('-') {
        let parts: Vec<&str> = key.split('-').collect();
        // last part must be single char or special
        if parts.last().unwrap().is_empty() {
            return false;
        }
        // check all parts non-empty
        for p in &parts {
            if p.is_empty() {
                return false;
            }
        }
        let last = parts.last().unwrap();
        let last_valid = last.chars().count() == 1 || specials.contains(&last.to_lowercase().as_str());
        if !last_valid {
            return false;
        }
        // earlier parts can be anything non-empty? (per observed, foo-a passes, so allow any)
        return true;
    }
    false
}

fn valid_action(action: &str) -> bool {
    if action.is_empty() {
        return false;
    }
    let lower = action.to_lowercase();
    let valid = [
        "help","quit","cancel","none","up","down","page_up","page_down",
        "toggle_pause","reset","toggle_color","toggle_reverse","toggle_line_number","toggle_border","toggle_forcus",
        "set_diff_only","next_keyword","prev_keyword","interval_plus","interval_minus",
        "move_top","move_end","scroll_left","scroll_right",
    ];
    valid.contains(&lower.as_str())
}

fn parse_keymap(s: &str) -> bool {
    // must contain exactly one '=', trim?
    // observed: "a=quit " (trailing space) passes, " a=quit" (leading space) passes
    // So trim? Actually keymap value "a=quit " includes trailing space, but passes. That suggests trim?
