use clap::{Arg, Command, ArgAction};
use std::env;
use std::process::{Command as ProcCommand, Stdio};
use std::time::{Duration, Instant};
use chrono::Local;
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ExecResult {
    timestamp: String,
    command: String,
    status: bool,
    output: String,
    stdout: String,
    stderr: String,
}

fn empty_result() -> ExecResult {
    ExecResult {
        timestamp: "".to_string(),
        command: "".to_string(),
        status: true,
        output: "".to_string(),
        stdout: "".to_string(),
        stderr: "".to_string(),
    }
}

fn get_command() -> Command {
    Command::new("hwatch")
        .version("0.3.19")
        .about("A modern alternative to the watch command, records the differences in execution results and can check this differences at after.")
        .arg(Arg::new("batch").short('b').long("batch").action(ArgAction::SetTrue).help("output execution results to stdout"))
        .arg(Arg::new("beep").short('B').long("beep").action(ArgAction::SetTrue).help("beep if command has a change result"))
