        .arg(Arg::new("mouse").long("mouse").action(ArgAction::SetTrue).help("enable mouse wheel support. With this option, copying text with your terminal may be harder. Try holding the Shift key."))
        .arg(Arg::new("color").short('c').long("color").action(ArgAction::SetTrue).help("interpret ANSI color and style sequences"))
        .arg(Arg::new("reverse").short('r').long("reverse").action(ArgAction::SetTrue).help("display text upside down."))
        .arg(Arg::new("compress").short('C').long("compress").action(ArgAction::SetTrue).help("Compress data in memory. Note: If the output of the command is small, you may not get the desired effect."))
        .arg(Arg::new("no-title").short('t').long("no-title").action(ArgAction::SetTrue).help("hide the UI on start. Use `t` to toggle it."))
        .arg(Arg::new("enable-summary-char").long("enable-summary-char").action(ArgAction::SetTrue).help("collect character-level diff count in summary."))
        .arg(Arg::new("line-number").short('N').long("line-number").action(ArgAction::SetTrue).help("show line number"))
        .arg(Arg::new("no-help-banner").long("no-help-banner").action(ArgAction::SetTrue).help("hide the \"Display help with h key\" message"))
        .arg(Arg::new("no-summary").long("no-summary").action(ArgAction::SetTrue).help("disable the calculation for summary that is running behind the scenes, and disable the summary function in the first place."))
        .arg(Arg::new("exec").short('x').long("exec").action(ArgAction::SetTrue).help("Run the command directly, not through the shell. Much like the `-x` option of the watch command."))
