    let parts: Vec<&str> = t.split('=').collect();
    if parts.len() != 2 {
        return false;
    }
    let key = parts[0];
    let action = parts[1];
    if key.is_empty() || action.is_empty() {
        return false;
    }
    // action may have trailing spaces? Already trimmed whole, but action internal? "a=quit " trimmed to "a=quit", ok.
    // key may have leading spaces? trimmed.
    if !valid_key(key) {
        return false;
    }
    if !valid_action(action) {
        return false;
    }
    true
}

