                        print!("Log to the same file? (Y/n) ");
                        use std::io::Write;
                        let _ = std::io::stdout().flush();
                        let mut input = String::new();
                        // read stdin; if EOF (0 bytes), proceed (as observed with None/EOF)
                        let n = std::io::stdin().read_line(&mut input).unwrap_or(0);
                        let proceed = if n == 0 {
                            true
                        } else {
                            let t = input.trim();
                            !(t.starts_with('n') || t.starts_with('N'))
