fn valid_action(action: &str) -> bool {
    let a = action.trim();
    if a.is_empty() { return false; }
    let lower = a.to_lowercase();
    let valid = ["help","quit","cancel","none","up","down","page_up","page_down","toggle_pause","reset","toggle_color","toggle_reverse","toggle_line_number","toggle_border","toggle_forcus","set_diff_only","next_keyword","prev_keyword","interval_plus","interval_minus","move_top","move_end","scroll_left","scroll_right"];
    valid.contains(&lower.as_str())
}

fn parse_keymap(s: &str) -> bool {
    let t = s.trim();
    let parts: Vec<&str> = t.split('=').collect();
    if parts.len() != 2 { return false; }
    let key = parts[0].trim();
    let action = parts[1].trim();
    if key.is_empty() || action.is_empty() { return false; }
    if !valid_key(key) { return false; }
    if !valid_action(action) { return false; }
    true
}

fn current_timestamp() -> String {
    Local::now().format("%Y-%m-%d %H:%M:%S%.3f").to_string()
}

fn main() {
    let hwatch_var = env::var("HWATCH").unwrap_or_default();
    let hwatch_args: Vec<String> = hwatch_var.split_whitespace().map(|s| s.to_string()).collect();
    let mut raw_args: Vec<String> = env::args().collect();
    let bin = raw_args.remove(0);
    let mut full_args = vec![bin];
    full_args.extend(hwatch_args);
    full_args.extend(raw_args);
    let cmd = get_command();
    let matches = match cmd.try_get_matches_from(full_args) {
        Ok(m) => m,
        Err(e) => { e.exit(); }
    };
    if let Some(kms) = matches.get_many::<String>("keymap") {
        for km in kms {
            if !parse_keymap(km) {
                eprintln!("Failed to parse keymap.");
                std::process::exit(1);
            }
        }
    }
    let batch: bool = matches.get_flag("batch");
    let beep: bool = matches.get_flag("beep");
    let reverse: bool = matches.get_flag("reverse");
    let line_number: bool = matches.get_flag("line-number");
    let exec_mode: bool = matches.get_flag("exec");
    let diff_output_only: bool = matches.get_flag("diff-output-only");
    let aftercommand: Option<String> = matches.get_one::<String>("aftercommand").cloned();
    let logfile: Option<String> = matches.get_one::<String>("logfile").cloned();
    let shell_str: String = matches.get_one::<String>("shell").cloned().unwrap_or("sh -c".to_string());
    let interval: f64 = *matches.get_one::<f64>("interval").unwrap_or(&2.0);
    let precise: bool = matches.get_flag("precise");
    let differences: Option<String> = matches.get_one::<String>("differences").cloned();
    let output_mode: String = matches.get_one::<String>("output").cloned().unwrap_or("output".to_string());
    let mut command_vec: Vec<String> = matches.get_many::<String>("command").map(|v| v.cloned().collect()).unwrap_or_default();
    let logfile_path: Option<String> = logfile.clone();
    if command_vec.is_empty() {
        if let Some(ref path) = logfile_path {
            match std::fs::read_to_string(path) {
                Ok(content) => {
                    if content.is_empty() {
                        eprintln!("error: command not specified and logfile is empty.\n\nUsage: hwatch [OPTIONS] [command]...\n\nFor more information, try '--help'.");
                        std::process::exit(2);
                    } else {
                        let mut found: Option<String> = None;
                        let mut had_parse_error = false;
                        let mut parse_err_detail = String::new();
                        for line in content.lines() {
                            if line.trim().is_empty() { continue; }
                            match serde_json::from_str::<serde_json::Value>(line) {
                                Ok(v) => {
                                    if let Some(c) = v.get("command").and_then(|x| x.as_str()) {
                                        if !c.is_empty() { found = Some(c.to_string()); }
                                    }
                                }
                                Err(e) => { had_parse_error = true; parse_err_detail = format!("{:?}", e); break; }
                            }
                        }
                        if had_parse_error {
                            eprint!("file \"{}\" is exists and json parse error.\n{}\n", path, parse_err_detail);
                            print!("Log to the same file? (Y/n) ");
                            use std::io::Write;
                            let _ = std::io::stdout().flush();
                            let mut input = String::new();
                            let _ = std::io::stdin().read_line(&mut input);
                            eprintln!("error: command not specified and logfile is empty.\n\nUsage: hwatch [OPTIONS] [command]...\n\nFor more information, try '--help'.");
                            std::process::exit(2);
                        } else {
                            if let Some(c) = found {
                                if let Some(parts) = shlex::split(&c) {
                                    if !parts.is_empty() { command_vec = parts; }
                                    else { command_vec = vec![c]; }
                                } else {
                                    command_vec = vec![c];
                                }
                            }
                            if command_vec.is_empty() {
                                eprintln!("error: command not specified and logfile is empty.\n\nUsage: hwatch [OPTIONS] [command]...\n\nFor more information, try '--help'.");
                                std::process::exit(2);
                            }
                        }
                    }
                }
                Err(_) => {
                    eprintln!("error: command not specified and logfile is empty.\n\nUsage: hwatch [OPTIONS] [command]...\n\nFor more information, try '--help'.");
                    std::process::exit(2);
                }
            }
        } else {
            eprintln!("error: command not specified and logfile is empty.\n\nUsage: hwatch [OPTIONS] [command]...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }
    if !batch {
        std::process::exit(0);
    }
    run_batch(beep, reverse, line_number, exec_mode, diff_output_only, aftercommand, logfile_path, shell_str, interval, precise, differences, output_mode, command_vec);
}

