fn execute_command(command_vec: &[String], cmd_str: &str, shell_str: &str, exec_mode: bool) -> (String, String, bool) {
    if exec_mode {
        let parts = shlex::split(cmd_str).unwrap_or_else(|| vec![cmd_str.to_string()]);
        if parts.is_empty() {
            return ("".to_string(), "".to_string(), true);
        }
        let prog = &parts[0];
        let args = &parts[1..];
        match std::process::Command::new(prog).args(args).output() {
            Ok(out) => {
                let so = String::from_utf8_lossy(&out.stdout).to_string();
                let se = String::from_utf8_lossy(&out.stderr).to_string();
                (so, se, out.status.success())
            }
            Err(e) => {
                let msg = format!("{} (os error {})", e.to_string().split(" (os error").next().unwrap_or(&e.to_string()), e.raw_os_error().unwrap_or(2));
                // Original for exec fail: "No such file or directory (os error 2)\n" ??? Actually output was "No such file or directory (os error 2)\n" without extra?
                // Our batch will add extra \n, so output should be "No such file..." without trailing \n? Let's return without \n, batch will add \n.
                // For shell fail via sh, output includes \n (from sh's stderr with \n). For exec fail, original output was "No such file..." with \n? Let's check: exec fail output was "No such file...\n" (single \n after header? Actually header + "No such...\n" (single). That's output "No such..." (no \n?) + extra \n => single. So return without \n.
                // e.to_string() is "No such file or directory (os error 2)" (no \n). Good.
                (String::new(), format!("{}\n", msg.trim()), false)
            }
        }
    } else {
        let shell_parts_opt = shlex::split(shell_str);
        let shell_parts = match shell_parts_opt {
            Some(v) => v,
            None => {
                // mimic original panic in background thread? For now, panic in main (will show different thread name, but rare)
                panic!("shell command parse error.: ParseError");
            }
        };
        if shell_parts.is_empty() {
            panic!("shell command parse error.: ParseError");
        }
        let has_placeholder = shell_str.contains("{COMMAND}");
        let mut full_args: Vec<String> = Vec::new();
        if has_placeholder {
            for tok in shell_parts {
                full_args.push(tok.replace("{COMMAND}", cmd_str));
            }
        } else {
            full_args = shell_parts;
            full_args.push(cmd_str.to_string());
        }
        let prog = full_args[0].clone();
        let args = full_args[1..].to_vec();
        // Use output to capture both separately. For combined output ordering (stderr+stdout), we use separate capture.
        // To mimic race for dual-stream? We use deterministic stderr+stdout.
        match std::process::Command::new(&prog).args(&args).output() {
            Ok(out) => {
                let so = String::from_utf8_lossy(&out.stdout).to_string();
                let se = String::from_utf8_lossy(&out.stderr).to_string();
                (so, se, out.status.success())
            }
            Err(e) => {
                // If shell itself not found? Unlikely. Return error as stderr?
                let msg = format!("{} (os error {})", e.to_string().split(" (os error").next().unwrap_or(&e.to_string()), e.raw_os_error().unwrap_or(2));
                (String::new(), format!("{}\n", msg.trim()), false)
            }
        }
    }
}
