enum DiffOp {
    Equal(usize, usize),
    Delete(usize),
    Insert(usize),
    Replace(usize, usize),
}

fn diff_lines(old: &[String], new: &[String]) -> Vec<DiffOp> {
    // Simple LCS DP for line diff
    let m = old.len();
    let n = new.len();
    if m == 0 && n == 0 {
        return Vec::new();
    }
    if m == 0 {
        return (0..n).map(|j| DiffOp::Insert(j)).collect();
    }
