        return (0..m).map(|i| DiffOp::Delete(i)).collect();
    }
    // DP table
    let mut dp = vec![vec![0; n+1]; m+1];
    for i in (0..m).rev() {
        for j in (0..n).rev() {
            if old[i] == new[j] {
                dp[i][j] = dp[i+1][j+1] + 1;
            } else {
                dp[i][j] = std::cmp::max(dp[i+1][j], dp[i][j+1]);
            }
        }
    }
    let mut ops = Vec::new();
    let mut i = 0;
    let mut j = 0;
    while i < m && j < n {
        if old[i] == new[j] {
            ops.push(DiffOp::Equal(i, j));
            i += 1; j += 1;
        } else if dp[i+1][j] >= dp[i][j+1] {
