import subprocess, time, signal, re, os
def run(bin, args, env=None, duration=1.0):
    e=dict(os.environ)
    if env: e.update(env)
    p=subprocess.Popen([bin]+args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=e)
    time.sleep(duration)
    alive=p.poll() is None
    if alive:
        p.send_signal(signal.SIGINT)
        try: out,err=p.communicate(timeout=4)
        except: p.kill(); out,err=p.communicate()
    else:
        out,err=p.communicate()
    out=re.sub(br'\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\.\d{3}', b'TS', out)
    err=re.sub(br'\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\.\d{3}', b'TS', err)
    return (p.returncode, out, err)

def cmp(args, env=None, dur=1.0):
    r1=run("/tmp/executable", args, env, dur)
    r2=run("./executable", args, env, dur)
    ok="OK" if r1==r2 else "DIFF"
    print(f"{ok} {args} env={env}")
